public String decentNumberBrute(int n) {
    String best = "-1";
    for (int mask = (1 << n) - 1; mask >= 0; mask--) {
        StringBuilder sb = new StringBuilder();
        int fives = 0, threes = 0;
        for (int b = n - 1; b >= 0; b--) {
            if ((mask & (1 << b)) != 0) { sb.append('5'); fives++; }
            else { sb.append('3'); threes++; }
        }
        if (fives % 3 == 0 && threes % 5 == 0) {
            String s = sb.toString();
            if (best.equals("-1") || s.compareTo(best) > 0) best = s;
        }
    }
    return best;
}

