from itertools import product

def decent_number_brute(n: int) -> str:
    best = "-1"
    for combo in product("53", repeat=n):
        s = "".join(combo)
        fives = s.count("5")
        threes = s.count("3")
        if fives % 3 == 0 and threes % 5 == 0:
            if best == "-1" or s > best:
                best = s
    return best

