public String decentNumber(int n) {
    for (int threes = 0; threes <= n; threes += 5) {
        int fives = n - threes;
        if (fives % 3 == 0) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < fives; i++) sb.append('5');
            for (int i = 0; i < threes; i++) sb.append('3');
            return sb.toString();
        }
    }
    return "-1";
}

